import sys

def primes(n):
	p = set()
	d = 2
	while d * d <= n:
		while n % d == 0:
			p.add(d)
			n //= d
		d += 1
	if n > 1:
		p.add(n)
	return p

def gcd(x, y):
	while y > 0:
		(x, y) = (y, x % y)
	return x
